			p5: "<strong>关于这个词。</strong>Gerrymandering(选区不公划分)是指为了让某个政党获得优势而划线。你可以从一份地图做了什么、以及人们对它如何被绘制所知的情况来辨认它。加拿大法律中没有以此命名的罪名,所以法院不会就选区不公划分本身作出裁决。这并不意味着它不会在这里发生。最接近的法律检验是《宪章》第 3 条下的有效代表权,下文会讲到。",
			p6: "<strong>如何阅读封面地图。</strong>封面按 2023 年每个投票区里人们的投票情况,为阿尔伯塔的 4,765 个投票区上色:NDP 选票集中的地方为橙色,UCP 选票集中的地方为蓝色。只有在大量人口居住的地方,颜色才会加深,所以一个铺展在数百平方公里林草地上的投票区会保持淡色。Ponoka 以西的土地是纯白色,因为那里没有投票站,也没有记录到任何人在那里居住或投票。上面的线是少数派地图提议的 89 个选区。<a href=\"__BASE__/explorer\">打开地图浏览器</a>,即可在全部三份地图之间切换。"
