			h3_1: "一座城市,四个选区",
			p2: "Airdrie 有 85,805 人(2024 年市政人口普查),一个市议会,一个学区。法律规定每个选区的人口上限为全省平均数的一又四分之一倍,所以 Airdrie 至少需要两个选区。多数派地图给它两个。",
			p3: "少数派地图给它四个:北部归入 Olds-Three Hills-Didsbury,东部归入 Airdrie East,西部归入 Calgary-Foothills-Airdrie West,中南部归入 Calgary-Airdrie。Airdrie East 占了全市一半以上,其居民中十有九人是 Airdrie 居民。全市其余人口几乎都被划入两个 Calgary 边缘选区,在那里 Calgary 居民多于 Airdrie 居民。北部那一块约有 350 人。这种分割越过了我预先注册的分散测试的第一道门槛:块数多于这座城市的规模所需。它没有越过第二道门槛——Airdrie 居民在每一块中都是少数——原因就在于 Airdrie East。按这项测试自己的规则,这不构成分散特征。多数派的两分法两道门槛都没有越过。",
			p4: "把一个社区拆得如此稀薄,使它在任何一个议席上都无法起决定作用,这叫作分散(cracking)。Airdrie East 以外的那部分 Airdrie,遭遇的正是这种情况。Airdrie 会有四位 MLA。选出其中三位的选民,大多数住在 Airdrie 以外。",
			h3_2: "NDP 最强的地方,选区更大",
			p5: "在 Calgary 东北部和中部的选区——NDP 在 2023 年赢得了那里 17 席中的 13 席——少数派地图的选区人口平均比全省平均水平高出 11.5%。多数派的平均高出 2.8%。选区越大,其中每一张选票的分量就越轻。把一个政党的选民放进数量更少、规模更大的选区,这叫作集中(packing)。这种模式符合我预先注册的集中测试。",
			h3_3: "选区大小不均",
			p6: "选区人口相等,是阿尔伯塔法律中唯一给出具体数字的价值。按委员会自己的人口表,少数派地图的选区平均偏离理想规模 4,707 人。多数派地图是 3,180 人。少数派的离散程度宽 48%。按 2021 年人口普查数字,差距会缩小:两份地图的平均偏差几乎相同,不过少数派的典型选区离相等仍然更远(3,938 对 2,827)。为奇怪的划线辩护,通常的说法是为了平衡人口才不得不如此。按委员会自己使用的数字,这个辩护在这里站不住。",
