			li3: "Olds–Three Hills–Didsbury 伸入 Airdrie 北部。",
			p10: "主席签署了多数派报告,所以你会预料他只批评少数派。但我在不知道他标记了哪些边界的情况下运行了几何测试,而这些测试独立地印证了他四处几何标记中的三处。",
			p11: "他称延伸进公园是为了争取一项人口保护条款——第 15(2) 条——而做的“恶意之举”;这项条款是为有人实际居住的偏远社区而写的。我的核查削弱了这一指控:即使没有这段延伸,这个选区也符合 s.15(2) 的条件。把 Banff 镇区与 Canmore 放在一起,作为利益共同体是说得通的,因为这个镇位于国家公园之中,无法向周围的公园土地扩展。他对延伸进空旷公园的反对依然成立。镇区的归属并不影响这一点。",
			h3_6: "议席优势",
			p12: "如果全省选票恰好对半分,下面是 UCP 在每份地图上的议席份额:",
			li4: "中位中立地图给出 44.8%;",
