			li6: "少数派地图给出 51.7%,位于第 99.99 百分位,1,010,000 张中立地图中只有 69 张超过它。",
			p13: "在少数派地图上,即使 UCP 的得票份额降到约 49.7%,它仍能保住组成多数所需的 45 席。在多数派地图上,它需要在普选票中领先约 4 个百分点。按 2023 年选举日的投票重演一遍,少数派地图给它 89 席中的 60 席。在多数派地图上是 55 席。",
			p14: "60 席是三分之二多数。在阿尔伯塔,这并不解锁任何特殊权力。简单多数就已经能通过法律和预算、援引截止辩论、修改议会规则,并确定每个委员会的成员构成。60 席会给政府一个缓冲。几位议员跨党转投也威胁不到它,而一个规模更小的反对党,用来维持委员会审查的成员也会更少。",
			p15: "这些选择没有一项违反阿尔伯塔的法律。该法允许分割城市,两份地图上的每个选区都在 ±25% 的范围之内。加拿大法律没有禁止党派优势本身的规则。它的检验标准是选民是否获得有效代表权。"
