			fig_caption: "党派偏斜从左到右;未通过的结构性测试从下到上。2019 年地图和 2026 年多数派地图位于安全角落(2019 年地图在对它运行的四项测试中一项也没有失败;Calgary 区域测试从未对它运行过)。少数派地图独自位于结构性离群线上,刚好未达到党派离群线。",
