			p5: "中立程序在四项公平性指标上产生少数派地图这种综合特征的几率,至多约为 568,000 分之 1(p ≤ 1.76×10⁻⁶,一个经 Bonferroni 校正、对依赖性稳健的上界)。我在两个地方找过,所以把原始数字翻了一倍。真实的几率至多是这个数,而且很可能更小。",
			p6: "这个数字不是地图清白的概率。那样理解它,就是“检察官谬误”。一份如此罕见的地图,仍然可能出自不寻常但诚实的判断。我的主张只是:普通的起草差异不是一个可信的解释。",
			h3_5: "用第二种方法核查",
			p7: "我把模拟的引擎换成了一个结构上不同的引擎——一个生成树森林(spanning-forest)采样器,事先在 OSF 登记(he53s),于 2026-07-10 运行。每项指标的百分位变动都不到一个百分点。另一个独立实现,即 R 的 redist 包,也没有找到任何达到少数派数值的方案。",
			h3_6: "模拟的局限",
			p8: "模拟强制执行人口和连续性(让每个选区连成一整块),但并没有强制执行委员会所权衡的每一项规则(s.15(2)、利益共同体、市政锚定)。它是一项有力的外部核查,而不是一份合法委员会可能画出的所有地图的清单。所以,不使用模拟的几何测试承担了大部分分量。平票测试隔离的是地图本身的贡献。在真实选举中,足够大的摇摆仍然可以压过任何地图的倾斜。",
			h3_7: "哪些没有站住",
