			li2: "<strong>效率差未达标。</strong>少数派为 +4.0%,位于第 94.5 百分位。预先注册的线是第 95 百分位(约 +4.1%),所以我把它报告为未达标。",
			li3: "<strong>机制测试失败了。</strong>我检验了被标记的形状是否产生了议席优势。在我的测试中,它们没有。形状和议席数字指向同一份地图,但两者之间的联系没有站住。",
			li4: "<strong>少数派完全通过了一项测试。</strong>在邻居排空测试(寻找紧挨着微弱差距选区的集中选区)上,它显示 1 个耦合信号,而多数派是 2 个,2019 年地图是 5 个。",
			li5: "<strong>两项统计没有站住。</strong>摆动区分配测试(Swing-Zone Allocation Test)在校正相邻地区投票相似之后,从 p = 0.0024 降到 p ≈ 0.19,因此只作为探索性结果(自 2026-06-13 起)。一千五百万分之一这个数字合并了两条并不独立的渠道,所以我不再使用它(自 2026-06-10 起)。",
