			p11: "少数派为其有争议的划线公开给出的理由,大多经不起公开数据的检验:六项中有五项经不起独立核查。通常是笼统的说法属实,而具体的那条线不然。Cochrane 约三分之一的劳动者通勤到 Calgary 的某处。这对走廊所伸入的 Nolan Hill 街区什么也说明不了。多数派没有公布这样的清单,所以这项核查只能单向进行。合起来看,少数派对多数派的两项指控描述的是两种不同的做法。多数派地图上,乡村选区更多但更满。少数派地图上,更少但更轻。",
			h3_9: "这是谁做的",
