			p2: "有两个事实很难用无心之失来解释。政府提名的委员画出了一份中立绘图几乎从不产生的地图:一百万次抽样中匹配的不到一百张。而当委员会没有认可这份地图、而是分裂时,政府没有问为什么。它把这项工作转给了一个由它自己的 MLA 控制的委员会。",
