			intro_p1: "对任何选举地图最干净的单一问题是:如果该省的选票在两大主要政党之间恰好平分,该地图会产生什么样的议席数?这保持选民基数不变,只问地图本身做了什么。",
			intro_p2: "为了回答这个问题,审计生成了 1,010,000 张计算机模拟、数学上中立的阿尔伯塔地图。模拟在委员会的地理基础上使用 Elections Alberta 官方 shapefile,使每一份方案都遵守相同的人口均衡(±25%)和连续性要求——这是该算法所强制执行的两项标准,而非每一项法定因素(例如,它并不强制执行利益共同体),因此该比较集最好被理解为人口与连续性中立,而非完全符合法定标准。然后将委员会的两份 2026 年地图放入该分布,以查看它们的常态程度。模拟运行四条独立链,每条 252,500 步,基础种子取自 Cloudflare drand 信标,并在执行前在 OSF 预先注册。",
