			ledger_r4_c: "恰好相反——少数派保留的乡村锚定选区更少(23 个对 28 个,2019 年为 31 个),并把更多乡村吸收进以城市命名的选区(7 个对 3 个)",
			ledger_r5_a: "多数派“拒绝使用”乡村阿尔伯塔的 ±25% 弹性",
