			heading: "关于我",
			p1: "我是 Mount Royal University 的一名学生。我独自完成了这项研究——它不是课程作业,大学也没有委托。我的观点是我自己的,不代表学校。约 27 年来,每逢选举,我都为 Elections Alberta 担任合同制选举工作人员,负责选举日的投票管理工作。我目前没有签约;上一次工作是在不久前的一次选举中。除此之外,我从未受雇于 Elections Alberta,对其工作的了解也仅限于这些任务。本次审计没有任何内容来自那份工作;所有输入数据都是公开的。这项研究是我自己的,不是 Elections Alberta 的,也不代表该机构发言。我与委员会没有关联。成年后,我对阿尔伯塔保守派和进步派的省级政党都投过票、捐过款。",
