			corr_municipal: "<strong>市政锚定。</strong>使用临时地图边界的早期草稿分析显示,少数派地图只有 15% 的时间锚定在市政界线上——比 70–85% 的加拿大常态低 4.9&times;。这个数字是临时(DPG 时期)边界重建造成的假象。在 Elections Alberta 官方标准 shapefile 上,两份地图的锚定都在加拿大常态范围内:多数派 80%,少数派 72%。两份地图在市政锚定上的<em>差异</em>,不是一个经得起标准重算的信号。委员会主席标记的三处边界异常(Rocky Mountain House–Banff Park、Nolan Hill–Cochrane、Olds–North Airdrie)仍然存在,不受这项更正影响。"
