			title: "建议 5(d):应恢复的乡村议席",
			body: "委员会主席 Dallas Miller 法官写道,如果立法机关不接受失去两个乡村选区,就应当把议席从 89 个增加到 91 个,并把它们恢复。这是他为恢复的议席点名的唯一地点:一个主要由 Clearwater 县和 Mountain View 县西部组成的选区,并具有 s. 15(2) 地位(该规则允许面积大、地处偏远的选区人口远低于平均数)。他要求的是考虑这一方案,而不是必须采用。图中轮廓是近似的:Clearwater 县,加上 Mountain View 县在 2019 年属于 Rimbey-Rocky Mountain House-Sundre 选区的那一部分。它完全位于 Airdrie 以北,也不占用任何受条件 (a) 或 (b) 保护的选区的土地。对于第二个议席,他没有点名任何地点。",
