				p1: "设想一个 40,000 人的小镇,大多投 Orange(橙党),位于一个大多投 Blue(蓝党)的地区。给这个小镇一个自己的选区——一个在立法机关拥有自己议席的区域——它就会选出一位橙党 MLA:40,000 人,一个议席,一个声音。现在把小镇切成四块,把每一块钉到一片蓝党乡村上。在每个新选区里,小镇的 10,000 名选民面对 30,000 名乡村选民。橙党四个选区全输。同样的选民,同样的选票,零个议席。没有任何一位选民被偷走了什么。被拿走的是<em>社区</em>选出任何人的能力。这就是分散(cracking)。它的镜像手法是集中(packing,附录 C):把一个群体塞进尽可能少的选区,让它在这些选区以压倒性优势获胜,在其他地方一无所获。",
