				p1: "因为这两台机器的构造不同,而假象(由机器的怪癖而不是由地图产生的结果)通常经不起更换机器。任何绘图算法都有怪癖。标准算法 ReCom 有一种有据可查的倾向,偏好紧凑、规整的选区,原则上这可能夸大一份不规则的真实地图看起来有多极端。所以审计更换了引擎。这个变体从随机生成的<em>森林</em>而不是树来生成选区,其内部行为有可测量的差异。它在用它画出任何一张地图之前就已公开登记(OSF he53s),它的种子取自一个任何人都可以验证的公开随机信标。如果少数派的尾部位置是第一台引擎怪癖造成的假象,第二台引擎就会让它移动。它在每项指标上的移动都不到一个百分位点:预先注册的“稳健”(ROBUST)判定。审计也报告了<em>失败</em>的那项核查。“第一幕中被标记的几何形态就是议席数字背后的具体机制”这一主张没有经受住检验,已被放弃。",
