				confusion: "<em>困惑:</em>“一项测试得出 p = 0.0024,你却把它扔掉了?这看起来像是在隐藏结果。”",
				p1: "恰恰相反:这是在更正结果。许多测试假设观察值相互独立,就像一次次单独的抛硬币。投票区不是这样。相邻的地区有相同的人口构成、收入和历史。它们投票相似。把 100 个聚集在一起的地区当作 100 次独立的抛硬币,实际上更像是 20 个有信息量的观察值穿了 100 件外套,这会让仅仅是不常见的巧合看起来像是不可能。解决办法是构建一个保留聚集性的零假设(即单凭偶然会产生什么的图景)。把相邻地区<em>成块</em>地一起打乱,而不是逐个地区打乱,然后再问一次同样的问题。审计的摆动区测试在朴素零假设下看起来显著(p = 0.0024),在校正后的零假设下则平平无奇(p ≈ 0.19)。当诚实的零假设与讨好的零假设不一致时,你保留诚实的那一个。并撤下这个结果。",
