				p1: "不凭什么特别的,而这正是重点:这项核查不需要任何特殊渠道。少数派报告说,Cochrane 居民会“顺畅地流动”到 Calgary。加拿大统计局的通勤表(免费、公开)显示,Cochrane 约三分之一的劳动者通勤到 Calgary,而约一半在 Cochrane 工作。这是真实的联系,但它对所画的那条具体的 Nolan Hill 走廊什么也说明不了。报告暗示共享的学校把 Red Deer 和 Sylvan Lake 联系在一起。这两个地方的学区边界(同样公开)把它们放在不同的学区。每一项核查都遵循同样的步骤。取出陈述的理由。找到能够显示它的公开数据集。看看<em>所画的那条具体的线</em>是不是数据所支持的那条线。在核查过的六项理由中,有五项在最后一步失败。联系是真实的;但那条线不是这种联系所指向的那条。",
