				confusion: "<em>困惑:</em>“政府提名的委员画出了偏向政府的地图。这下总可以结案了吧?”",
				p1: "阿尔伯塔的委员会由提名构成:一位主席,加上由政府方和反对党方提名的委员。这种设计预设了党派视角,并让它们相互平衡。它押注的是,一个成员混合的房间会汇聚到一份站得住的地图上。几十年来,这个赌注都押对了:委员会签署的都是一致通过的报告。这一轮,这个房间沿着提名的界线分裂了,而政府提名的委员产出了统计上的离群地图。这种相关性是真实的,值得记录下来。而推论也必须恰好在这里停下。被提名的委员不是代理人。本次审计的记录中没有任何证据表明,政府在提交之前指使了其提名委员、与他们协同,甚至知道他们地图的形状。历史上让提名者失望的被提名者比比皆是。这种相关性引出一个问题。它无法回答这个问题。而且当数据指向主席一方时,审计的工具也会切向主席一方。这就是对称测量的含义。",
