				confusion: "<em>困惑:</em>“立法机关怎么能就这样……接管选区重划?委员会的地图不就是那份地图吗?”",
				p1: "不是。这是整件事中承重的那个意外。根据阿尔伯塔的 <em>Electoral Boundaries Commission Act</em>,委员会提出方案;只有立法议会作出决定。委员会的最终报告——连同听证、意见和修改——是建议。在立法议会颁布一份地图之前,它没有任何法律效力。而且该法对立法议会改而做什么没有施加任何约束:没有最低辩论要求,没有通知期,没有优先采用委员会工作的义务,对随后的任何程序也没有听证要求。该法中没有任何内容阻止立法议会把这项工作交给别处。政府第 37 号动议正是这样做的,把它交给了一个特别委员会。立法议会的特别委员会由 MLA 组成,所以选择这个载体本身就排除了独立性。合法地。自该法于 1995 年修订以来的每一轮中,让政客的手远离那支笔的,是立法议会的自我克制,而不是法规。1992 年并非如此。一个由 MLA 组成的委员会绘制了地图,而 1994 年上诉法院指责该委员会无法解释其中好几条边界。",
