				confusion: "<em>困惑:</em>“如果政客为自己划选区违反了我们最深层的选举规范,它怎么可能合法?”",
				p1: "因为加拿大的宪法运行在两套操作系统上。一套是法律:成文的、可诉的(法院可以就其作出裁决)、由法院强制执行。另一套是惯例:不成文的政治行为规则,在实践中有约束力,在法庭上却看不见。最高法院在 1981 年的《宪法回归咨询案》(Patriation Reference)中描述了这一分野。法院可以<em>承认</em>一项惯例,却仍然拒绝<em>强制执行</em>它,因为惯例是由政治来监督的——由反对党、媒体和选民——而不是由司法来监督。独立边界委员会处在惯例这一边。六十年的实践,在每个省和联邦层面,确立了政客不为自己划选区这条规则。任何地方都没有法规把这条规则定为强制性的。所以这道护栏的全部力量,在于历届政府一直选择尊重它。一项规范一旦被违反而没有后果,对之后的每一届政府来说都会变弱。无论是哪个政党。",
