				p1: "一台计算机绘制了 <strong>1,010,000 张合法的阿尔伯塔地图</strong>。每一张都遵守真实委员会所遵守的同样两条硬性规则:每个选区的人数都接近相同(在平均数的 25% 以内),每个选区都连成一整块。",
				p2: "计算机是怎么画地图的?一次一小步。取两个有共同边界的选区。把它们合并成一团。再把这一团随机切回两个新的合法选区。重复 1,010,000 次,每一步之后都保存地图。这种方法叫作 ReCom,是这一领域的标准工具。",
				p3: "关键的事实是:<strong>计算机从不看任何选票。</strong>它不知道 NDP 或 UCP 的选民住在哪里。所以,如果一张中立地图仍然倾向某一边,这种倾斜就只来自阿尔伯塔的地理。而如果一份真实地图倾斜的程度远远超过几乎所有中立地图,地理就不再能作为解释。",
				p4: "关于这台机器的四点如实说明:",
				li1: "<strong>骰子是公开掷的。</strong>随机种子(每一次随机选择背后的起始数字)不是作者挑选的。它来自一个公开随机信标(“drand”,由包括 Cloudflare 在内的团体 League of Entropy 运营),就像一次现场直播的彩票开奖。它在官方地图文件出现之前就已锁定。任何人都可以重新计算它。",
				li2: "<strong>四次独立运行结果一致。</strong>这一百万张地图来自四次独立运行,每次的起点都不同。四次运行都收敛到同样的图景。用于检验这一点的标准检查(整个领域通用)都以充裕的余量通过。",
				li3: "<strong>关于议席数的说明。</strong>2026 年委员会的两份地图各有 89 个选区。模拟在 87 个选区的 2019 年地图上运行,这是最后一份依法颁布的地图,因为算法需要一份真实地图作为出发点。11 月的委员会将产出 91 个选区。本网站上的每一个百分比都是议席<em>份额</em>,所以这些数字在三种规模之间可以直接比较。",
				li4: "<strong>这台机器不是完美的裁判。</strong>它遵守两条硬性规则,但并不遵守真实委员会所尊重的每一条软性规则,比如把社区保持在一起。真实的委员会地图实际上比大多数中立地图更规整。凡是出现这台机器数字的地方,审计都明确说明了这一点。"
