				p2: "“第 99.99 百分位”就不同了。它意味着这份地图比队列中几乎每一张中立地图都更倾斜——在本次审计中,是除了 <strong>1,010,000 张中的 69 张</strong>以外的全部。身高也是同样的道理。处于第 78 百分位的男子算是稍高。处于第 99.99 百分位的男子身高约七英尺。"
