				li1: "<strong>1. 人口离散度。</strong>各选区偏离理想规模多远?按委员会自己的人口表,多数派地图的典型偏离为 3,180 人。少数派地图为 4,707 人,宽了大约一半。偏离越大,选票的分量就越不平等。",
				li2: "<strong>2. Calgary 拥挤。</strong>在 Calgary 东北部和中部,少数派地图的选区比全省平均水平大 11.5%。多数派的大 2.8%。选区越大,其中每一张选票的分量就越轻。而这个区域大量投 NDP。这种模式叫作<em>集中</em>(packing)。",
