				li1: "<strong>1. 平票时的议席。</strong>最直观的测试。假设全省恰好以 50/50 投票,然后数一数每一方的议席。在阿尔伯塔的地理上,一张典型的中立地图在平票时给 UCP 约 44.8% 的议席。城市的 NDP 选票被利用得稍微更有效率一些,所以平票自然会略微有利于 NDP。多数派地图给 UCP 46.1%:第 78 百分位,普通。少数派地图给 UCP <strong>51.7%</strong>,在选票打平的情况下拿到多数议席。1,010,000 张中立地图中只有 69 张对 UCP 更有利。作为参照,一个被要求<em>刻意</em>最大化 UCP 议席的程序达到了 52.9%。少数派地图离这个人为设计出的上限,比离中立的中间位置更近。",
				li2: "<strong>2. 效率差。</strong>每一张选票要么是赢得议席所需的,要么是“浪费”的——投给了落选者,或者在胜选者身上堆积超出了获胜所需。这项指标比较各政党的选票被浪费的速度。多数派地图得分 +0.1%:基本为零。少数派得分 +4.0%,有利于 UCP,位于第 94.5 百分位,刚好<em>低于</em>审计预设在第 95 百分位的警戒线。这是唯一一项没有触发的指标。审计把它报告为未达标。",
				li3: "<strong>3. 均值-中位差。</strong>比较一个政党各选区结果的平均值与居中选区的结果。当两者拉开距离时,说明有选票在某处被堆进一边倒的大胜里。少数派地图的差距比 99.9% 的中立地图更有利于 UCP。多数派的差距则倾向另一边——NDP 的选票效率略高——这与规整的委员会地图在阿尔伯塔地理上的表现一致。",
