				p2: "看待这份评分卡的另一种方式:它是<em>第三条轴</em>。审计的图表在两个维度上绘制每一份地图:结构和统计。迄今为止绘制的三份地图,都出自在这里得分九项中九项的边界委员会程序,所以第三条轴一直没有什么可以区分。11 月的地图,将是审计历史上第一个背后有不同程序得分的点。",
				p3: "诚实地阅读这张表,从两个方向读。边界委员会得分九项中九项,这是<em>由构造决定的</em>。这些标准描述的是这项规范所建立的制度,而边界委员会就是那个制度。有信息量的部分是向前看的。MLA 委员会的“否”和“待定”格子中,有四项是它从现在到 11 月之间仍然可以补上的特征:听证、公布草案、新的意见,以及由它们带来的回应性。如果它补上了这些,审计关于程序偏离的发现就会得到实质性的缓和,而审计已经以书面形式承诺会如实说明这一点。",
